import packageManifest from "../../../package.json" with { type: "json" };
export const PACKAGE_NAME = packageManifest.name;
export const PACKAGE_VERSION = packageManifest.version;
export const GENERATOR_IDENTITY = Object.freeze({
    name: PACKAGE_NAME,
    version: PACKAGE_VERSION,
});
export function isSemVer(value) {
    if (typeof value !== "string")
        return false;
    return /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-(?:(?:0|[1-9]\d*)|(?:\d*[A-Za-z-][0-9A-Za-z-]*))(?:\.(?:(?:0|[1-9]\d*)|(?:\d*[A-Za-z-][0-9A-Za-z-]*)))*)?(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?$/.test(value);
}
export function assertCompatibleGenerator(identity, owner) {
    const candidate = identity;
    const version = candidate?.version;
    if (candidate?.name !== PACKAGE_NAME || !isSemVer(version) || !version.startsWith("1.")) {
        throw new Error(`${owner}: requires a 1.x ${PACKAGE_NAME} generator identity.`);
    }
}
